// Local, deterministic SQL generation only. Never connects to Supabase.
import { readFileSync, writeFileSync } from 'node:fs'
const data = JSON.parse(readFileSync(new URL('../src/data/catalog-expansion.json', import.meta.url), 'utf8'))
const quote = value => `'${String(value).replaceAll("'", "''")}'`
const array = (values, type = 'text') => `array[${values.map(quote).join(',')}]::${type}[]`
const rows = [
  '-- REVIEW REQUIRED. Additive reference data for installed migrations 001–004.',
  '-- Generated by scripts/generate-catalog-migration.mjs. No hosted execution.',
  'begin;',
]
for (const source of data.sources) {
  const keys = Object.keys(source)
  rows.push(`insert into public.evidence_sources(${keys.join(',')}) values (${keys.map(key => typeof source[key] === 'number' ? source[key] : quote(source[key])).join(',')});`)
}
for (const exercise of data.exercises) {
  const keys = Object.keys(exercise)
  rows.push(`insert into public.exercises(${keys.join(',')}) values (${keys.map(key => Array.isArray(exercise[key]) ? array(exercise[key], key === 'evidence_source_ids' ? 'uuid' : 'text') : typeof exercise[key] === 'number' ? exercise[key] : quote(exercise[key])).join(',')});`)
}
for (const alternative of data.alternatives) {
  rows.push(`insert into public.exercise_alternatives(exercise_id,alternative_exercise_id,similarities,differences,suitability_notes,source_ids) values (${[alternative.exercise_id, alternative.alternative_exercise_id, alternative.similarities, alternative.differences, alternative.suitability_notes].map(quote).join(',')},${array(alternative.source_ids,'uuid')});`)
}
rows.push('commit;', '')
writeFileSync(new URL('../supabase/migrations/202610180005_catalog_expansion.sql', import.meta.url), rows.join('\n'))
